(* [comment removed for export] *)
Lemma nodup_map_inj : forall {A B} (f : A -> B) (l : list A) a b,
  List.NoDup (map f l) -> In a l -> In b l -> f a = f b -> a = b.
Proof.
  intros A B f l. induction l as [|x l IH]; intros a b ND Ia Ib E; [destruct Ia|].
  cbn in ND. inversion ND as [|y l' NI ND']; subst.
  destruct Ia as [<- | Ia]; destruct Ib as [<- | Ib]; [reflexivity | | | exact (IH a b ND' Ia Ib E)].
  - exfalso. apply NI. rewrite E. apply in_map. exact Ib.
  - exfalso. apply NI. rewrite <- E. apply in_map. exact Ia.
Qed.

Lemma in_app_keep : forall {A} (b x : A) (L1 L2 : list A), In b (L1 ++ x :: L2) -> b = x \/ In b (L1 ++ L2).
Proof.
  intros A b x L1 L2 IN. apply in_app_or in IN. destruct IN as [IN | [<- | IN]]; [right | left; reflexivity | right]; apply in_or_app; [left | right]; exact IN.
Qed.

Lemma mod16_mod8 : forall P a, P mod 16 = 0 -> (P + 8 * a) mod 8 = 0.
Proof.
  intros P a M. apply Z.mod_divide in M; [|lia]. destruct M as [k Hk]. rewrite Hk.
  replace (k * 16 + 8 * a) with ((2 * k + a) * 8) by lia. apply Z_mod_mult.
Qed.

Section HCW.
  Context {HCEIL : HeapCeil}.

(* [comment removed for export] *)
Lemma FieldsOwn_keep : forall LB LB' em (X : Z),
  FieldsOwn LB em -> (forall b, In b LB -> In b LB' \/ blk_addr b = X) -> (forall e d, em !! e = Some d -> e <> X) -> FieldsOwn LB' em.
Proof.
  intros LB LB' em X OWN KEEP NX e d Le. destruct (OWN e d Le) as [p [IN SZ]]. exists p. split; [| exact SZ].
  destruct (KEEP _ IN) as [K | K]; [exact K | exfalso; exact (NX e d Le K)].
Qed.

Lemma MBufOwn_keep : forall LB LB' es (X : Z),
  MBufOwn LB es -> (forall b, In b LB -> In b LB' \/ blk_addr b = X) -> (forall x s, In (x, s) es -> x <> X) -> MBufOwn LB' es.
Proof.
  intros LB LB' es X OWN KEEP NX x s IN. destruct (OWN x s IN) as [p INb]. exists p.
  destruct (KEEP _ INb) as [K | K]; [exact K | exfalso; exact (NX x s IN K)].
Qed.

Lemma SvOwnP_keep : forall LB LB' ptr len (X : Z),
  SvOwnP LB ptr len -> (forall b, In b LB -> In b LB' \/ blk_addr b = X) -> (1 <= len -> ptr <> X) -> SvOwnP LB' ptr len.
Proof.
  intros LB LB' ptr len X [K | (L1 & p & IN)] KEEP NX; [left; exact K | right]. split; [exact L1|]. exists p.
  destruct (KEEP _ IN) as [K | K]; [exact K | exfalso; exact (NX L1 K)].
Qed.

Lemma HdrOwnP_keep : forall LB LB' h (X : Z),
  HdrOwnP LB h -> (forall b, In b LB -> In b LB' \/ blk_addr b = X) ->
  (1 <= hv_ml h -> hv_mp h <> X) -> (1 <= hv_tl h -> hv_tp h <> X) -> HdrOwnP LB' h.
Proof.
  intros LB LB' h X (O1 & O2 & R1 & R2) KEEP N1 N2. split; [| split; [| split; [exact R1 | exact R2]]].
  - eapply SvOwnP_keep; [exact O1 | exact KEEP | exact N1].
  - eapply SvOwnP_keep; [exact O2 | exact KEEP | exact N2].
Qed.

Lemma fb_ok_keep : forall LB LB' F (X : Z),
  fb_ok LB F -> (forall b, In b LB -> In b LB' \/ blk_addr b = X) -> (F <> FB_empty -> fb_begin F <> X) -> fb_ok LB' F.
Proof.
  intros LB LB' F X [K | (p & IN & R)] KEEP NX; [left; exact K | right]. exists p. split; [| exact R].
  destruct (KEEP _ IN) as [K | K]; [exact K | exfalso]. apply NX; [| exact K]. intros ->. destruct R as ((R1 & _) & _). cbn in R1. lia.
Qed.

Lemma FlatBuf_keep : forall LB LB' m a F ds (X : Z),
  FlatBuf LB m a F ds -> (forall b, In b LB -> In b LB' \/ blk_addr b = X) -> (F <> FB_empty -> fb_begin F <> X) -> FlatBuf LB' m a F ds.
Proof.
  intros LB LB' m a F ds X (C & OK & SZ & BLK) KEEP NX. split; [exact C|]. split; [eapply fb_ok_keep; [exact OK | exact KEEP | exact NX]|]. split; [exact SZ | exact BLK].
Qed.

Lemma StateBlock_keep : forall LB LB' m b ioc implb S ds (X : Z),
  StateBlock LB m b ioc implb S ds -> (forall x, In x LB -> In x LB' \/ blk_addr x = X) -> b <> X ->
  (st_fb S <> FB_empty -> fb_begin (st_fb S) <> X) -> StateBlock LB' m b ioc implb S ds.
Proof.
  intros LB LB' m b ioc implb S ds X (p & j7 & j16 & j4 & IN & RB & CH & OK & EV & CE & CW & PM & FB & REST) KEEP NB NF.
  exists p, j7, j16, j4. split; [destruct (KEEP _ IN) as [K | K]; [exact K | exfalso; exact (NB K)]|].
  split; [exact RB|]. split; [exact CH|]. split; [exact OK|]. split; [exact EV|]. split; [exact CE|]. split; [exact CW|]. split; [exact PM|].
  split; [eapply FlatBuf_keep; [exact FB | exact KEEP | exact NF] | exact REST].
Qed.

Section SR.
  Variable H : hsr.
  Hypothesis HH : heap_sr_hyps H.

(* [comment removed for export] *)
Lemma blocks_apart : forall s LB m b1 b2,
  hs_RHEAP H s LB m -> In b1 LB -> In b2 LB -> blk_addr b1 <> blk_addr b2 ->
  blk_addr b1 + blk_size b1 <= blk_addr b2 \/ blk_addr b2 + blk_size b2 <= blk_addr b1.
Proof.
  intros s LB m b1 b2 HP I1 I2 NE. destruct (bptr_eq_dec (blk_id b1) (blk_id b2)) as [E | D].
  - exfalso. apply NE. rewrite (nodup_map_inj blk_id LB b1 b2 (hh_nodup H HH _ _ _ HP) I1 I2 E). reflexivity.
  - exact (hh_disj H HH _ _ _ _ _ HP I1 I2 D).
Qed.

(* [comment removed for export] *)
Lemma same_block : forall s LB m p1 p2 A n1 n2,
  hs_RHEAP H s LB m -> In (p1, A, n1) LB -> In (p2, A, n2) LB -> 0 < n1 -> 0 < n2 -> (p1, A, n1) = (p2, A, n2).
Proof.
  intros s LB m p1 p2 A n1 n2 HP I1 I2 P1 P2. destruct (bptr_eq_dec p1 p2) as [E | D].
  - exact (nodup_map_inj blk_id LB _ _ (hh_nodup H HH _ _ _ HP) I1 I2 E).
  - exfalso. destruct (hh_disj H HH _ _ _ _ _ HP I1 I2 D) as [K | K]; cbn in K; lia.
Qed.

(* [comment removed for export] *)
Lemma lb_remove_split : forall L1 x L2,
  List.NoDup (map blk_id (L1 ++ x :: L2)) -> hs_lb_remove H (blk_id x) (L1 ++ x :: L2) = L1 ++ L2.
Proof.
  pose proof (hh_lb_remove H HH) as (R1 & R2 & R3).
  induction L1 as [|b L1 IH]; intros x L2 ND.
  - cbn in ND |- *. destruct x as [[p A] n]. cbn. apply R1. inversion ND; subst. exact H2.
  - cbn in ND |- *. inversion ND as [|y l NI ND']; subst.
    rewrite R2; [rewrite (IH x L2 ND'); reflexivity|].
    intros E. apply NI. rewrite E. rewrite map_app. apply in_or_app. right. left. reflexivity.
Qed.

(* [comment removed for export] *)
Lemma elems_off_block : forall s LB m mm Fa S L ns ls em q A n,
  hs_RHEAP H s LB m -> FieldsC mm Fa S L ns ls em -> FieldsOwn LB em -> In (q, A, n) LB ->
  (forall e, e ∈ L -> e <> A) ->
  forall e d, em !! e = Some d -> e + esize d <= A \/ A + n <= e.
Proof.
  intros s LB m mm Fa S L ns ls em q A n HP FC OWN INq NX e d Le.
  pose proof FC as (_ & _ & _ & _ & _ & _ & _ & LEQ & _).
  destruct (OWN e d Le) as [pe [INe _]].
  assert (He : e ∈ L) by (apply (proj2 (LEQ e)); rewrite Le; eexists; reflexivity).
  destruct (blocks_apart _ _ _ (pe, e, esize d) (q, A, n) HP INe INq ltac:(cbn; exact (NX e He))) as [K | K]; cbn in K; lia.
Qed.

(* [comment removed for export] *)
Lemma body_off_block : forall s LB m mm b es insz q A n,
  hs_RHEAP H s LB m -> MBuf mm b es insz -> MBufOwn LB es -> In (q, A, n) LB ->
  (forall x sz, In (x, sz) es -> x <> A) ->
  forall x sz, In (x, sz) es -> x + 24 + sz <= A \/ A + n <= x.
Proof.
  intros s LB m mm b es insz q A n HP MB OWN INq NX x sz IN.
  destruct (OWN x sz IN) as [p INb]. pose proof (mb_ok_size _ _ _ _ (proj2 MB) IN) as SZ.
  pose proof (mb_block_size_range sz ltac:(lia)) as [BR _].
  destruct (blocks_apart _ _ _ (p, x, mb_block_size sz) (q, A, n) HP INb INq ltac:(cbn; exact (NX x sz IN))) as [K | K]; cbn in K; lia.
Qed.
