(* [comment removed for export] *)
Definition rs_at_dbpret (C : rsc) (sp : word) (s7v s6v s5v s4v s3v s2v s1v s0v ra : word) (fr0 : list word) (M0 : Z) (w : rsw) (n : Z) (cf : config) : Prop :=
  exists (t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s5x s6x s7x t3 t4 t5 t6 : word) (m : mem) (tot : Z) (j8 j7 : list byte) (t1c : list cell),
    cfg_ms cf = rs_ms RS_DBPRET (wz RS_DBPRET) sp (c_gp C) (c_tp C) t0 t1 t2 tot (c_P C) a0 a1 a2 a3 a4 a5 a6 a7 s5x s6x s7x (c_s8 C) (c_s9 C) (c_s10 C) (c_s11 C) t3 t4 t5 t6 (c_F C) (c_fc C) m
    /\ pc_state (ps_c (w_d w)) <> 11
    /\ hs_KREL H (ps_st (w_d w)) (cfg_model cf) /\ hs_MPRES H (c_mo0 C) (cfg_model cf)
    /\ rs_core H C sp s7v s6v s5v s4v s3v s2v s1v s0v ra fr0 w EC_clear tot m j8 t1c
         [CB 1 [b8 1]; CB 7 j7; C8 (wz (fb_out (w_FB w))); C8 (wz n)]
    /\ fb_last (w_FB w) = fb_out (w_FB w) + n /\ 512 <= n <= 65536 /\ w_FB w <> FB_empty
    /\ (fb_end (w_FB w) <= c_stb C \/ c_stb C + SZ_SPCI_STATE <= fb_begin (w_FB w))
    /\ (w_Fs w = FB_empty \/ (fb_end (w_FB w) <= fb_begin (w_Fs w) \/ fb_end (w_Fs w) <= fb_begin (w_FB w)))
    /\ wM (c_N C) w <= M0.

(* [comment removed for export] *)
Lemma rs_read_A : forall (C : rsc) (sp : word) (s7v s6v s5v s4v s3v s2v s1v s0v ra : word) (fr0 : list word) (M0 : Z) (w : rsw) (cf : config),
  rs_static C -> bv_unsigned sp = c_P C - 64 ->
  rs_at_doread H C sp s7v s6v s5v s4v s3v s2v s1v s0v ra fr0 M0 w cf ->
  hs_SR H (fun cf' => exists w' n, w_sds w' = w_sds w /\ rs_at_dbpret C sp s7v s6v s5v s4v s3v s2v s1v s0v ra fr0 M0 w' n cf') cf.
Proof.
  intros C sp s7v s6v s5v s4v s3v s2v s1v s0v ra fr0 M0 w cf STC SPE AT.
  pose proof STC as STC0.
  destruct C as [P N lo B stb implb A LBin pad7 pad2 j13 j32a j8a j32b j8b mb m0 mo0 gp tp s8w s9w s10 s11 F fc].
  destruct w as [d PB FBB FB fds Fs sds nr]. destruct d as [c S L ns ls em h u es insz g rdi LBn st errv].
  destruct cf as [ms mo]. unfold rs_at_doread, rs_core, rs_frames, RWm, rs_static in *. cbn_w_all. cbn [cfg_ms cfg_model] in AT.
  destruct STC as (P0 & PBB & BHI & AL16 & CEIL & IMG & LO & NR26 & (p7 & INS) & RBS & INA & TP & MB1).
  destruct AT as (rax & t0 & t1 & t2 & a0 & a1 & a2 & a3 & a4 & a5 & a6 & a7 & s5x & s6x & s7x & t3 & t4 & t5 & t6 & m & E & tot & j8 & t1c & t2c
                  & -> & NS11 & KREL & MP & (RM & RP & ST & (FRM & FRhi & FR0 & LFR0) & XP0 & TOT0 & TOT & NRB) & WM0).
  destruct RM as (PC & UW & RDI & J13 & J32a & J8a & J32b & J8b & HC & FTS & MV & FBU & EC & BS & SB & HP & ERR & AUX & MI).
  pose proof RP as RP0. unfold RWp in RP. cbn_w_all.
  destruct RP as (PCOK & OWN & MOWN & HOWN & EH & ESH & DFB & HST & U01 & CAP & LES & INZ & LEN1 & HDJ & HL8 & SK62
                  & AOWN & PERM & FOK & FRL & FRB & FRT & FRM_ & FRF & DJL & DJB & DJT & DJM & STRM & SZS & NRK & CPM & BY & CN & IZ).
  assert (LOP : lo + 13136 <= P) by (clear - LO; unfold SRO_STACK in LO; lia).
  assert (LOD : lo + 64 + 128 + DBP_STACK <= P) by (clear - LO; unfold SRO_STACK in LO; unfold DBP_STACK, FB_PREPARE_STACK, ROPNEW_STACK, RMALLOC_STACK; lia).
  hcb. pose proof (bv_unsigned_in_range 64 sp) as SPR. unfold bv_modulus in SPR. change (2 ^ Z.of_N 64) with (2^64) in SPR.
  subst tp.
  pose proof (FlatBuf_shape _ _ _ _ _ FBU) as (FS1 & FS2 & FS3 & FS4 & FS5). pose proof (FlatBuf_size _ _ _ _ _ FBU) as FSZ.
  pose proof (read_size_val_range FB) as RSV.
  destruct FRM as (F8 & T1 & SZT1 & T2 & SZT2).
  destruct (rw_cells_forget _ _ _ _ T2) as [jt2 T2b]. rewrite SZT2 in T2b. clear T2.
  pose proof UW as (FC & HDR & USED & MB & RD & MRG & CBH & CBB & PFT & FI & XS).
  pose proof RBS as (RB1 & RB2 & RB3 & RB4 & RB5). unfold SZ_SPCI_STATE in RB4, RB5.
  (* [comment removed for export] *)
  pose proof rs_doread1 as DR. unfold rs_doread1_stmt, rs_ms, RS_DOREAD, RS_DBPRET, O_H_EC, O_H_FB, O_H_STREAM in DR. unfold wz in DR.
  unfold rs_ms, RS_DOREAD, O_H_EC, O_H_FB, O_H_STREAM. unfold wz.
  eapply (hh_evt_then H HH); [exact KREL | |].
